```js
const DIGITS = '0123456789';

function digitClass(n) {
  if (n <= 0) return '';
  if (n === 1) return '\\d';
  return `\\d{${n}}`;
}

function charClass(lo, hi) {
  if (lo === hi) return lo;
  const a = lo.charCodeAt(0), b = hi.charCodeAt(0);
  if (a === b - 1) return `${lo}${hi}`;
  return `[${lo}-${hi}]`;
}

function alternatives(lo, hi) {
  const len = lo.length;
  if (len === 0) return [''];
  if (lo === hi) return [lo];
  // all zero to all nine -> any digit of that width
  if (lo === '0'.repeat(len) && hi === '9'.repeat(len)) {
    return [len === 1 ? '\\d' : `\\d{${len}}`];
  }
  // full range with no leading zero: 10..99, 100..999, ...
  if (lo === '1' + '0'.repeat(len - 1) && hi === '9'.repeat(len)) {
    return [`[1-9]${digitClass(len - 1)}`];
  }
  if (lo[0] === hi[0]) {
    return alternatives(lo.slice(1), hi.slice(1)).map(s => lo[0] + s);
  }
  const out = [];
  const p = lo[0];
  const q = hi[0];
  const pi = p.charCodeAt(0) - 48;
  const qi = q.charCodeAt(0) - 48;
  for (const s of alternatives(lo.slice(1), '9'.repeat(len - 1))) {
    out.push(p + s);
  }
  if (qi - pi > 1) {
    out.push(charClass(String.fromCharCode(pi + 1 + 48), String.fromCharCode(qi - 1 + 48)) + digitClass(len - 1));
  }
  for (const s of alternatives('0'.repeat(len - 1), hi.slice(1))) {
    out.push(q + s);
  }
  return out;
}
