const MAX_SAFE = Number.MAX_SAFE_INTEGER;

function toInteger(value, name) {
  const n = typeof value === 'string' ? Number(value) : value;
  if (typeof n !== 'number' || !Number.isInteger(n)) {
    throw new TypeError(`${name} must be an integer, got ${JSON.stringify(value)}`);
  }
  if (!Number.isSafeInteger(n)) {
    throw new RangeError(`${name} must be a safe integer`);
  }
  return n;
}

function digitSuffix(count) {
  if (count <= 0) return '';
  if (count === 1) return '\\d';
  return `\\d{${count}}`;
}

function digitClassRange(lo, hi) {
  if (lo === hi) return lo;
  if (lo === '0' && hi === '9') return '\\d';
  return `[${lo}-${hi}]`;
}

function alternatives(lo, hi) {
  const len = lo.length;
  if (len === 0) return [''];
  if (len === 1) return [digitClassRange(lo, hi)];
  if (lo === hi) return [lo];
  if (lo === '0'.repeat(len) && hi === '9'.repeat(len)) {
    return [digitSuffix(len)];
  }
  if (lo === `1${'0'.repeat(len - 1)}` && hi === '9'.repeat(len)) {
    return [`[1-9]${digitSuffix(len - 1)}`];
  }
  if (lo[0] === hi[0]) {
    return alternatives(lo.slice(1), hi.slice(1)).map((suffix) => lo[0] + suffix);
  }
  const out = [];
  const p = lo[0];
  const q = hi[0];
  const pi = Number(p);
  const qi = Number(q);
  for (const suffix of alternatives(lo.slice(1), '9'.repeat(len - 1))) {
    out.push(p + suffix);
  }
  if (qi - pi > 1) {
    out.push(`[${pi + 1}-${qi - 1}]${digitSuffix(len - 1)}`);
  }
  for (const suffix of alternatives('0'.repeat(len - 1), hi.slice(1))) {
    out.push(q + suffix);
  }
  return out;
}
```

