export function rangeToRegex(min, max, options = {}) {
  const { anchor = true } = options;
  let lo = toInteger(min, 'min');
  let hi = toInteger(max, 'max');
  if (lo > hi) [lo, hi] = [hi, lo];
  if (lo < 0) throw new RangeError('range bounds must be non-negative');

  const loStr = String(lo);
  const hiStr = String(hi);
  const alternativesList = [];
  for (let len = loStr.length; len <= hiStr.length; len++) {
    const lower = len === 1 ? lo : Math.max(lo, 10 ** (len - 1));
    const upper = Math.min(hi, 10 ** len - 1);
    if (lower > upper) continue;
    alternativesList.push(...alternatives(String(lower), String(upper)));
  }
  const factored = factorAlternatives(alternativesList);
  const body = factored.length === 1 ? factored[0] : `(?:${factored.join('|')})`;
  return anchor ? `^(?:${body})$` : body;
}
```

