```js
export function parseRange(input) {
  const match = /^\s*(-?\d+)\s*-\s*(-?\d+)\s*$/.exec(String(input));
  if (!match) {
    throw new TypeError(`invalid numeric range: ${JSON.stringify(input)}`);
  }
  return [Number(match[1]), Number(match[2])];
}
```

