{
  "name": "range-to-regex",
  "version": "1.0.0",
  "description": "Convert a numeric range such as 1-100 into a single regular expression that matches any number in that range.",
  "type": "module",
  "main": "index.js",
  "bin": {
    "range-to-regex": "cli.js"
  },
  "files": [
    "index.js",
    "cli.js"
  ],
  "scripts": {
    "start": "node cli.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "keywords": [
    "regex",
    "regexp",
    "range",
    "numbers",
    "numeric-range"
  ],
  "license": "MIT"
}

function toInteger(value, name) {
  const number = typeof value === "string" ? Number(value) : value;
  if (typeof number !== "number" || !Number.isInteger(number)) {
    throw new TypeError(`${name} must be an integer, received ${JSON.stringify(value)}`);
  }
  if (!Number.isSafeInteger(number)) {
    throw new RangeError(`${name} must be a safe integer`);
  }
  return number;
}

function digitSuffix(count) {
  if (count <= 0) return "";
  if (count === 1) return "\\d";
  return `\\d{${count}}`;
}

function digitClassRange(low, high) {
  if (low === high) return low;
  if (low === "0" && high === "9") return "\\d";
  return `[${low}-${high}]`;
}

function alternatives(low, high) {
  const length = low.length;
  if (length === 0) return [""];
  if (length === 1) return [digitClassRange(low, high)];
  if (low === high) return [low];
  if (low === "0".repeat(length) && high === "9".repeat(length)) {
    return [digitSuffix(length)];
  }
  if (low === `1${"0".repeat(length - 1)}` && high === "9".repeat(length)) {
    return [`[1-9]${digitSuffix(length - 1)}`];
  }
  if (low[0] === high[0]) {
    return alternatives(low.slice(1), high.slice(1)).map((suffix) => low[0] + suffix);
  }

  const out = [];
  const firstLow = low[0];
  const firstHigh = high[0];
  const lowDigit = Number(firstLow);
  const highDigit = Number(firstHigh);

  for (const suffix of alternatives(low.slice(1), "9".repeat(length - 1))) {
    out.push(firstLow + suffix);
  }
  if (highDigit - lowDigit > 1) {
    out.push(`[${lowDigit + 1}-${highDigit - 1}]${digitSuffix(length - 1)}`);
  }
  for (const suffix of alternatives("0".repeat(length - 1), high.slice(1))) {
    out.push(firstHigh + suffix);
  }
  return out;
}

function splitTrailingDigits(alternative) {
  if (alternative.endsWith("\\d")) {
    return { base: alternative.slice(0, -2), count: 1 };
  }
  const match = /\\d\{(\d+)\}$/.exec(alternative);
  if (match) {
    return { base: alternative.slice(0, match.index), count: Number(match[1]) };
  }
  return { base: alternative, count: 0 };
}

function digitRun(start, end) {
  if (start === 0 && end === 1) return "\\d?";
  if (start === 0) return `\\d{0,${end}}`;
  if (start === end) return start === 1 ? "\\d" : `\\d{${start}}`;
  return `\\d{${start},${end}}`;
}

function factorAlternatives(list) {
  const countsByBase = new Map();
  for (const alternative of list) {
    const { base, count } = splitTrailingDigits(alternative);
    if (base === "") continue;
    if (!countsByBase.has(base)) countsByBase.set(base, new Set());
    countsByBase.get(base).add(count);
  }

  const out = [];
  const emitted = new Set();
  const ungrouped = new Set();

  for (const alternative of list) {
    const { base } = splitTrailingDigits(alternative);
    if (base === "") {
      if (!ungrouped.has(alternative)) {
        ungrouped.add(alternative);
        out.push(alternative);
      }
      continue;
    }
    if (emitted.has(base)) continue;
    emitted.add(base);

    const counts = [...countsByBase.get(base)].sort((a, b) => a - b);
    let start = counts[0];
    let end = counts[0];
    const runs = [];
    for (let i = 1; i < counts.length; i++) {
      if (counts[i] === end + 1) {
        end = counts[i];
      } else {
        runs.push([start, end]);
        start = counts[i];
        end = counts[i];
      }
    }
    runs.push([start, end]);

    for (const [runStart, runEnd] of runs) {
      if (runStart === 0 && runEnd === 0) out.push(base);
      else out.push(base + digitRun(runStart, runEnd));
    }
  }

  return out;
}

/**
 * Build a regular expression source string that matches any integer in
 * `[min, max]`. The result is anchored with `^...$` unless `anchor` is false.
 */
export function rangeToRegex(min, max, options = {}) {
  const { anchor = true } = options;

  let low = toInteger(min, "min");
  let high = toInteger(max, "max");
  if (low > high) [low, high] = [high, low];
  if (low < 0) throw new RangeError("range bounds must be non-negative");

  const lowStr = String(low);
  const highStr = String(high);
  const collected = [];

  for (let length = lowStr.length; length <= highStr.length; length++) {
    const lower = length === 1 ? low : Math.max(low, 10 ** (length - 1));
    const upper = Math.min(high, 10 ** length - 1);
    if (lower > upper) continue;
    collected.push(...alternatives(String(lower), String(upper)));
  }

  const factored = factorAlternatives(collected);
  const body = factored.length === 1 ? factored[0] : `(?:${factored.join("|")})`;
  return anchor ? `^(?:${body})$` : body;
}

/** Parse a string such as "1-100" into `[1, 100]`. */
export function parseRange(input) {
  const match = /^\s*(-?\d+)\s*-\s*(-?\d+)\s*$/.exec(String(input));
  if (!match) throw new TypeError(`invalid numeric range: ${JSON.stringify(input)}`);
  return [Number(match[1]), Number(match[2])];
}

/** Return true when `value` falls inside the given range. */
export function matches(range, value, options = {}) {
  const [min, max] = typeof range === "string" ? parseRange(range) : range;
  const regex = new RegExp(rangeToRegex(min, max, { ...options, anchor: true }));
  return regex.test(String(value));
}

export default rangeToRegex;

#!/usr/bin/env node
import process from "node:process";
import { rangeToRegex, parseRange } from "./index.js";

const USAGE = `Usage: range-to-regex <min-max> [options]

Convert a numeric range into a single regular expression.

Options:
  --no-anchor   Print the pattern without the ^...$ anchors
  -h, --help    Show this help message

Examples:
  range-to-regex 1-100
  range-to-regex 0-255 --no-anchor
`;

function main(argv) {
  const args = argv.slice(2);

  if (args.includes("-h") || args.includes("--help")) {
    process.stdout.write(USAGE);
    return 0;
  }
  if (args.length === 0) {
    process.stderr.write(USAGE);
    return 1;
  }

  const anchor = !args.includes("--no-anchor");
  const rangeArg = args.find((arg) => !arg.startsWith("-"));
  if (!rangeArg) {
    process.stderr.write(`error: missing numeric range\n\n${USAGE}`);
    return 1;
  }

  try {
    const [min, max] = parseRange(rangeArg);
    process.stdout.write(`${rangeToRegex(min, max, { anchor })}\n`);
    return 0;
  } catch (error) {
    process.stderr.write(`error: ${error.message}\n`);
    return 1;
  }
}

process.exitCode = main(process.argv);

import test from "node:test";
import assert from "node:assert/strict";
import { rangeToRegex, parseRange, matches } from "../index.js";

test("parseRange understands 'min-max' strings", () => {
  assert.deepEqual(parseRange("1-100"), [1, 100]);
  assert.deepEqual(parseRange(" 5 - 10 "), [5, 10]);
  assert.deepEqual(parseRange("0-0"), [0, 0]);
  assert.throws(() => parseRange("abc"), /invalid numeric range/);
  assert.throws(() => parseRange("1..100"), /invalid numeric range/);
});

test("the canonical 1-100 example", () => {
  const source = rangeToRegex(1, 100);
  const regex = new RegExp(source);
  for (const n of [1, 9, 10, 42, 99, 100]) {
    assert.ok(regex.test(String(n)), `${n} should match ${source}`);
  }
  for (const n of [0, 101, 1000]) {
    assert.ok(!regex.test(String(n)), `${n} should not match ${source}`);
  }
  assert.equal(matches("1-100", 100), true);
  assert.equal(matches("1-100", 0), false);
});

test("anchoring can be disabled", () => {
  const anchored = rangeToRegex(1, 9);
  const loose = rangeToRegex(1, 9, { anchor: false });
  assert.ok(anchored.startsWith("^"));
  assert.ok(anchored.endsWith("$"));
  assert.equal(anchored, `^(?:${loose})$`);
});

test("inputs may be swapped and reject negatives", () => {
  assert.equal(rangeToRegex(100, 1), rangeToRegex(1, 100));
  assert.throws(() => rangeToRegex(-1, 10), /non-negative/);
  assert.throws(() => rangeToRegex(1.5, 10), /integer/);
});

test("matches every integer in every small range", () => {
  const limit = 100;
  const checkTo = 130;
  for (let min = 0; min <= limit; min++) {
    for (let max = min; max <= limit; max++) {
      const source = rangeToRegex(min, max, { anchor: true });
      const regex = new RegExp(source);
      for (let value = 0; value <= checkTo; value++) {
        const expected = value >= min && value <= max;
        assert.equal(
          regex.test(String(value)),
          expected,
          `range ${min}-${max}: ${value} against ${source}`,
        );
      }
    }
  }
});

test("handles wide ranges that cross digit-length boundaries", () => {
  const cases = [
    [0, 9],
    [0, 10],
    [9, 11],
    [5, 9999],
    [100, 999],
    [123, 4567],
    [98, 102],
    [1000, 1000],
  ];
  for (const [min, max] of cases) {
    const regex = new RegExp(rangeToRegex(min, max));
    const samples = [min, max, min - 1, max + 1, Math.floor((min + max) / 2)].filter(
      (n) => n >= 0,
    );
    for (const value of samples) {
      assert.equal(
        regex.test(String(value)),
        value >= min && value <= max,
        `range ${min}-${max}: ${value} against ${rangeToRegex(min, max)}`,
      );
    }
  }
});

